window.VOCAB_DATA["1"] = {"id":1,"title":"时间与存在","version":"20260618-1","words":[{"k":"ch1:1","id":1,"word":"atmosphere","phonetic":"/ˈætməsfɪə/","pos":"n.","tag":"核心","meaning":"大气层，大气圈；气氛","root":"atmo（水汽）+ sphere（球体，球形）→ 大气圈","exEN":"The planet's thick atmosphere traps heat and keeps the surface warm.","exCN":"这颗行星厚厚的大气层锁住热量，使表面保持温暖。","extra":""},{"k":"ch1:2","id":2,"word":"hydrosphere","phonetic":"/ˈhaɪdrəʊsfɪə/","pos":"n.","tag":"核心","meaning":"水圈；大气中的水汽","root":"hydro（水）+ sphere（球体，球形）→ 水圈","exEN":"The hydrosphere covers about 70% of the Earth's surface.","exCN":"水圈覆盖了地球表面约70%。","extra":""},{"k":"ch1:3","id":3,"word":"lithosphere","phonetic":"/ˈlɪθəʊsfɪə/","pos":"n.","tag":"核心","meaning":"岩石圈","root":"litho（石头）+ sphere（球体，球形）→ 岩石圈","exEN":"Scientists study the lithosphere to understand how continents drift over time.","exCN":"科学家研究岩石圈以了解大陆如何随时间漂移。","extra":""},{"k":"ch1:4","id":4,"word":"oxygen","phonetic":"/ˈɒksɪdʒən/","pos":"n.","tag":"核心","meaning":"氧气","root":"oxy（酸）+ gen（产生）→ 早期误以为所有酸都含氧而得名","exEN":"Plants absorb carbon dioxide and release oxygen during photosynthesis.","exCN":"植物在光合作用中吸收二氧化碳并释放氧气。","extra":""},{"k":"ch1:5","id":5,"word":"oxide","phonetic":"/ˈɒksaɪd/","pos":"n.","tag":"核心","meaning":"氧化物","root":"ox(y)（氧）+ ide（化合物后缀）→ 氧化物","exEN":"Rust is a common type of iron oxide that forms when metal is exposed to moisture.","exCN":"铁锈是一种常见的氧化铁，当金属接触水分时就会形成。","extra":""},{"k":"ch1:6","id":6,"word":"carbon dioxide","phonetic":"/ˈkɑːbən daɪˈɒksaɪd/","pos":"n.","tag":"核心","meaning":"二氧化碳","root":"carbon（碳）+ di（二）+ oxide（氧化物）→ 二氧化碳","exEN":"Burning coal in power stations releases large amounts of carbon dioxide into the air.","exCN":"发电站燃烧煤炭会向空气中释放大量二氧化碳。","extra":""},{"k":"ch1:7","id":7,"word":"hydrogen","phonetic":"/ˈhaɪdrədʒən/","pos":"n.","tag":"核心","meaning":"氢气","root":"hydro（水）+ gen（生成）→ 燃烧后生成水的元素","exEN":"Hydrogen fuel is widely studied as a clean energy substitute for oil.","exCN":"氢燃料作为石油的清洁替代能源，正在被广泛研究。","extra":""},{"k":"ch1:8","id":8,"word":"core","phonetic":"/kɔː/","pos":"n.","tag":"高频","meaning":"中心，核心；地核","root":"源自拉丁语 cor（心）→ 核心、中心","exEN":"At the core of any great school lies a strong team of teachers.","exCN":"任何优秀学校的核心都有一支强大的教师团队。","extra":""},{"k":"ch1:9","id":9,"word":"crust","phonetic":"/krʌst/","pos":"n.","tag":"高频","meaning":"地壳；外壳","root":"源自拉丁语 crusta（硬壳）→ 外壳","exEN":"The outermost crust of the Earth is broken into many tectonic plates.","exCN":"地球最外层的地壳分裂成了多个构造板块。","extra":""},{"k":"ch1:10","id":10,"word":"mantle","phonetic":"/ˈmæntl/","pos":"n.","tag":"高频","meaning":"地幔；斗篷，披风","root":"源自拉丁语 mantellum（披风）→ 覆盖物；地幔","exEN":"Below the crust lies the mantle, which is thousands of kilometres thick.","exCN":"地壳之下是厚达数千公里的地幔。","extra":""},{"k":"ch1:11","id":11,"word":"longitude","phonetic":"/ˈlɒndʒɪtjuːd/","pos":"n.","tag":"高频","meaning":"经度","root":"long（长）+ -itude（表示状态）→ 经度","exEN":"Using longitude and latitude, navigators can pinpoint any location on the ocean.","exCN":"利用经纬度，航海者可以精确定位海洋上任何一处。","extra":""},{"k":"ch1:12","id":12,"word":"latitude","phonetic":"/ˈlætɪtjuːd/","pos":"n.","tag":"高频","meaning":"纬度","root":"lat（宽）+ -itude（表示状态）→ 纬度","exEN":"Cities located at higher latitudes receive much less sunlight in winter.","exCN":"高纬度城市在冬天接收的阳光要少得多。","extra":""},{"k":"ch1:13","id":13,"word":"horizon","phonetic":"/həˈraɪzən/","pos":"n.","tag":"核心","meaning":"地平线；眼界，见识","root":"源自希腊语 horizon（界限）→ 地平线；眼界","exEN":"Watching the sun disappear below the ocean horizon is a breathtaking experience.","exCN":"看着太阳消失在海平面之下是一种令人屏息的体验。","extra":""},{"k":"ch1:14","id":14,"word":"altitude","phonetic":"/ˈæltɪtjuːd/","pos":"n.","tag":"核心","meaning":"高度，海拔","root":"alt（高）+ -itude（表示性质、状态）→ 高度","exEN":"Hikers often struggle with low oxygen when they reach high altitudes.","exCN":"徒步者在到达高海拔地区时通常会因低氧而感到吃力。","extra":""},{"k":"ch1:15","id":15,"word":"disaster","phonetic":"/dɪˈzɑːstə/","pos":"n.","tag":"核心","meaning":"灾难","root":"dis（表示否定）+ aster（星星）→ 星相不吉 → 灾难","exEN":"The oil leak caused an environmental disaster along the entire coastline.","exCN":"这次石油泄漏给整条海岸线带来了环境灾难。","extra":""},{"k":"ch1:16","id":16,"word":"mishap","phonetic":"/ˈmɪshæp/","pos":"n.","tag":"高频","meaning":"小灾难","root":"mis（坏的，错的）+ hap（运气）→ 不幸；小事故","exEN":"A slight mishap in the laboratory caused a short delay to the experiment.","exCN":"实验室的一个小事故让实验短暂推迟。","extra":""},{"k":"ch1:17","id":17,"word":"catastrophic","phonetic":"/ˌkætəˈstrɒfɪk/","pos":"adj.","tag":"高频","meaning":"灾难性的","root":"源自希腊语 katastrophē（翻转；毁灭）→ 灾难性的","exEN":"A sudden rise in sea levels could have catastrophic effects on coastal cities.","exCN":"海平面突然上升可能会给沿海城市带来灾难性后果。","extra":""},{"k":"ch1:18","id":18,"word":"calamity","phonetic":"/kəˈlæməti/","pos":"n.","tag":"高频","meaning":"灾难，不幸的事","root":"源自拉丁语 calamitas（灾害，损失）→ 灾难","exEN":"Years of conflict turned the once peaceful valley into a calamity zone.","exCN":"多年的冲突把曾经安宁的山谷变成了一片灾区。","extra":""},{"k":"ch1:19","id":19,"word":"endanger","phonetic":"/ɪnˈdeɪndʒə/","pos":"v.","tag":"核心","meaning":"使遭受危险，危及","root":"en（使）+ danger（危险）→ 使遭受危险","exEN":"The increase in plastic waste endangers birds and sea creatures.","exCN":"塑料垃圾的增加危及鸟类和海洋生物。","extra":""},{"k":"ch1:20","id":20,"word":"jeopardise","phonetic":"/ˈdʒepədaɪz/","pos":"v.","tag":"核心","meaning":"危害，危及","root":"源自古法语 jeu parti（平分的棋局）→ 危险处境 → 危及","exEN":"Pollution from nearby factories jeopardises the local water supply.","exCN":"附近工厂的污染危及当地供水。","extra":""},{"k":"ch1:21","id":21,"word":"destructive","phonetic":"/dɪˈstrʌktɪv/","pos":"adj.","tag":"核心","meaning":"破坏性的，有害的","root":"de（除去）+ struct（建造）+ -ive（形容词后缀）→ 破坏性的","exEN":"The destructive storm swept through several villages, leaving hundreds homeless.","exCN":"这场破坏性风暴席卷了好几个村庄，数百人流离失所。","extra":""},{"k":"ch1:22","id":22,"word":"El Nino","phonetic":"/el ˈniːnjəʊ/","pos":"n.","tag":"识记","meaning":"厄尔尼诺现象","root":"西班牙语“圣婴”，指南美沿岸海水异常增温现象","exEN":"During El Nino periods, fishing yields near Peru tend to drop sharply.","exCN":"在厄尔尼诺期间，秘鲁附近的渔获量往往会大幅下降。","extra":""},{"k":"ch1:23","id":23,"word":"greenhouse","phonetic":"/ˈɡriːnhaʊs/","pos":"n.","tag":"核心","meaning":"温室，暖房","root":"green（绿色，植物）+ house（房屋）→ 温室","exEN":"Crops grown in a greenhouse are protected from extreme cold and pests.","exCN":"在温室中种植的作物能免于极寒和虫害侵袭。","extra":""},{"k":"ch1:24","id":24,"word":"phenomenon","phonetic":"/fɪˈnɒmɪnən/","pos":"n.","tag":"核心","meaning":"现象","root":"pheno（显示，出现）+ menon（名词后缀）→ 现象","exEN":"The sudden phenomenon caught the attention of scientists around the world.","exCN":"这一突然现象引起了全球科学家的注意。","extra":""},{"k":"ch1:25","id":25,"word":"pebble","phonetic":"/ˈpebl/","pos":"n.","tag":"低频","meaning":"鹅卵石","root":"源自古英语 papol（小石子）→ 鹅卵石","exEN":"She picked up a smooth white pebble as a souvenir of the beach.","exCN":"她捡起一块光滑的白色鹅卵石当作海滩的纪念。","extra":""},{"k":"ch1:26","id":26,"word":"magnet","phonetic":"/ˈmæɡnɪt/","pos":"n.","tag":"高频","meaning":"磁铁，吸铁石","root":"源自希腊语 Magnēsia（马格内西亚，古地名）→ 磁石","exEN":"The child used a magnet to collect all the scattered metal pins.","exCN":"孩子用一块磁铁把所有散落的大头针吸了起来。","extra":""},{"k":"ch1:27","id":27,"word":"ore","phonetic":"/ɔː/","pos":"n.","tag":"高频","meaning":"矿石；矿","root":"源自古英语 ōra（黄铜，矿石）→ 矿石","exEN":"The region is known for its rich deposits of copper and iron ore.","exCN":"该地区以丰富的铜矿和铁矿而闻名。","extra":""},{"k":"ch1:28","id":28,"word":"mineral","phonetic":"/ˈmɪnərəl/","pos":"n.","tag":"核心","meaning":"矿物，矿物质；矿产","root":"mine（矿山）+ -eral（表示名词）→ 矿物","exEN":"Many cereals are fortified with essential minerals like zinc and iron.","exCN":"许多谷物食品都强化添加了锌和铁等必需矿物质。","extra":""},{"k":"ch1:29","id":29,"word":"marble","phonetic":"/ˈmɑːbl/","pos":"n.","tag":"高频","meaning":"大理石；弹球","root":"源自希腊语 marmaros（闪光的石头）→ 大理石","exEN":"The floor of the cathedral was made of polished white marble.","exCN":"大教堂的地面由抛光白色大理石铺成。","extra":""},{"k":"ch1:30","id":30,"word":"quartz","phonetic":"/kwɔːts/","pos":"n.","tag":"低频","meaning":"石英","root":"源自德语 Quarz，可能来自斯拉夫语（硬的）→ 石英","exEN":"The watch is powered by a tiny quartz crystal that vibrates constantly.","exCN":"这块表由一颗不断振动的小石英晶体驱动。","extra":""},{"k":"ch1:31","id":31,"word":"granite","phonetic":"/ˈɡrænɪt/","pos":"n.","tag":"低频","meaning":"花岗岩","root":"gran（颗粒）+ -ite（名词后缀）→ 有颗粒的石头 → 花岗岩","exEN":"The old bridge was built from solid granite and survived several floods.","exCN":"这座古桥用坚固的花岗岩建成，历经多次洪水仍屹立不倒。","extra":""},{"k":"ch1:32","id":32,"word":"gust","phonetic":"/ɡʌst/","pos":"n.","tag":"高频","meaning":"一阵狂风；迸发","root":"源自古诺斯语 gustr（风）→ 一阵狂风","exEN":"A powerful gust of wind blew the papers off the outdoor table.","exCN":"一阵强风把文件从户外桌上吹落。","extra":""},{"k":"ch1:33","id":33,"word":"breeze","phonetic":"/briːz/","pos":"n.","tag":"高频","meaning":"微风，和风","root":"可能源自西班牙语 brisa（东北风）→ 微风","exEN":"We enjoyed a gentle evening breeze as we walked along the beach.","exCN":"我们沿着海滩散步时享受着傍晚轻柔的微风。","extra":""},{"k":"ch1:34","id":34,"word":"monsoon","phonetic":"/mɒnˈsuːn/","pos":"n.","tag":"高频","meaning":"季风；雨季","root":"源自阿拉伯语 mausim（季节）→ 季风","exEN":"Farmers in South Asia depend on the monsoon to water their rice fields.","exCN":"南亚的农民依赖季风给稻田浇水。","extra":""},{"k":"ch1:35","id":35,"word":"gale","phonetic":"/ɡeɪl/","pos":"n.","tag":"高频","meaning":"大风","root":"起源不确定，可能源自古诺斯语 gal（狂风）→ 大风","exEN":"The ship radioed for help as it was caught in a fierce gale.","exCN":"那艘船遭遇狂风，发出无线电求救。","extra":""},{"k":"ch1:36","id":36,"word":"hurricane","phonetic":"/ˈhʌrɪkən/","pos":"n.","tag":"高频","meaning":"飓风；暴风","root":"源自西班牙语 huracán，来自加勒比土著语风暴之神 → 飓风","exEN":"Coastal residents evacuated their homes before the hurricane made landfall.","exCN":"沿海居民在飓风登陆前撤离了家园。","extra":""},{"k":"ch1:37","id":37,"word":"tornado","phonetic":"/tɔːˈneɪdəʊ/","pos":"n.","tag":"高频","meaning":"龙卷风","root":"可能源自西班牙语 tronada（雷暴）→ 龙卷风","exEN":"The tornado lifted farm vehicles off the ground and tossed them aside.","exCN":"龙卷风把农用车辆掀离地面，抛到一旁。","extra":""},{"k":"ch1:38","id":38,"word":"typhoon","phonetic":"/taɪˈfuːn/","pos":"n.","tag":"高频","meaning":"台风","root":"源自汉语粤方言“大风”（daai fung）→ 台风","exEN":"Ferry services were suspended as the typhoon grew stronger overnight.","exCN":"随着台风夜间加强，渡轮服务暂停。","extra":""},{"k":"ch1:39","id":39,"word":"volcano","phonetic":"/vɒlˈkeɪnəʊ/","pos":"n.","tag":"高频","meaning":"火山","root":"源自罗马神话火神 Vulcan（武尔坎）→ 火山","exEN":"Tourists gathered at the viewpoint to watch the volcano erupt at sunset.","exCN":"游客聚集在观景台观看日落时分的火山喷发。","extra":""},{"k":"ch1:40","id":40,"word":"erupt","phonetic":"/ɪˈrʌpt/","pos":"v.","tag":"高频","meaning":"爆发，喷发；突然出现","root":"e（向外）+ rupt（破裂）→ 向外破裂 → 爆发","exEN":"Thick smoke and ash erupted from the crater, darkening the sky.","exCN":"浓烟和火山灰从火山口喷出，天空变得昏暗。","extra":""},{"k":"ch1:41","id":41,"word":"magma","phonetic":"/ˈmæɡmə/","pos":"n.","tag":"识记","meaning":"岩浆","root":"源自希腊语 magma（揉捏，浓厚的软膏）→ 岩浆","exEN":"As magma rises closer to the surface, it can trigger tremors in nearby areas.","exCN":"当岩浆上升接近地表时，会引发附近地区的震动。","extra":""},{"k":"ch1:42","id":42,"word":"thermodynamic","phonetic":"/ˌθɜːməʊdaɪˈnæmɪk/","pos":"adj.","tag":"识记","meaning":"热力的；热力学的","root":"thermo（热）+ dynamic（力的；力学）→ 热力的；热力学的","exEN":"The engine was designed using advanced thermodynamic principles for better fuel efficiency.","exCN":"这台发动机采用先进热力学原理设计，以提高燃油效率。","extra":""},{"k":"ch1:43","id":43,"word":"smog","phonetic":"/smɒɡ/","pos":"n.","tag":"高频","meaning":"烟雾，雾霾","root":"smoke（烟）+ fog（雾）→ 烟雾","exEN":"The city banned many older cars to reduce the smog that covered its streets.","exCN":"该市禁止许多旧车上路，以减少覆盖街道的雾霾。","extra":""},{"k":"ch1:44","id":44,"word":"fume","phonetic":"/fjuːm/","pos":"n.","tag":"高频","meaning":"烟，气体","root":"源自拉丁语 fumus（烟）→ 烟，气体","exEN":"Workers wore masks to avoid inhaling the toxic fumes from burning plastics.","exCN":"工人戴着口罩以避免吸入燃烧塑料产生的有毒烟气。","extra":""},{"k":"ch1:45","id":45,"word":"mist","phonetic":"/mɪst/","pos":"n.","tag":"高频","meaning":"薄雾；水汽；使视线模糊的东西","root":"源自古英语 mist（薄雾）→ 薄雾","exEN":"A cold mist rolled off the river, making it hard to see the opposite bank.","exCN":"一股寒冷的薄雾从河面升起，使对岸难以看清。","extra":""},{"k":"ch1:46","id":46,"word":"tsunami","phonetic":"/tsuːˈnɑːmi/","pos":"n.","tag":"高频","meaning":"海啸","root":"源自日语“津波”（港口波浪）→ 海啸","exEN":"The earthquake generated a huge tsunami that swept over the coastal villages.","exCN":"地震引发了巨大的海啸，淹没了沿海村庄。","extra":""},{"k":"ch1:47","id":47,"word":"drought","phonetic":"/draʊt/","pos":"n.","tag":"高频","meaning":"干旱，旱灾","root":"词源同 dry（干燥的）→ 干旱","exEN":"Long months of drought forced the local government to restrict water use.","exCN":"长达数月的干旱迫使当地政府限制用水。","extra":""},{"k":"ch1:48","id":48,"word":"flooding","phonetic":"/ˈflʌdɪŋ/","pos":"n.","tag":"高频","meaning":"洪水泛滥","root":"flood（洪水）+ -ing（表示过程）→ 洪水泛滥","exEN":"The flooding submerged the entire ground floor of the hospital.","exCN":"洪水淹没了医院整个一楼。","extra":""},{"k":"ch1:49","id":49,"word":"torrent","phonetic":"/ˈtɒrənt/","pos":"n.","tag":"高频","meaning":"激流，洪流","root":"源自拉丁语 torrens（急流）→ 激流","exEN":"After the heavy rain, a torrent of brown water rushed down the mountain.","exCN":"大雨过后，一股棕色的激流从山上奔涌而下。","extra":""},{"k":"ch1:50","id":50,"word":"earthquake","phonetic":"/ˈɜːθkweɪk/","pos":"n.","tag":"核心","meaning":"地震","root":"earth（地球）+ quake（震动）→ 地震","exEN":"The earthquake rattled windows and knocked books off the shelves.","exCN":"地震震得窗户咯吱响，把书架上的书震落。","extra":""},{"k":"ch1:51","id":51,"word":"seismic","phonetic":"/ˈsaɪzmɪk/","pos":"adj.","tag":"高频","meaning":"地震的，地震引起的","root":"源自希腊语 seismos（地震）→ 地震的","exEN":"Researchers placed sensors across the fault to monitor seismic changes.","exCN":"研究人员在断层各处放置传感器以监测地震变化。","extra":""},{"k":"ch1:52","id":52,"word":"avalanche","phonetic":"/ˈævəlɑːnʃ/","pos":"n.","tag":"高频","meaning":"雪崩","root":"源自古法语 avaler（下降）→ 雪崩","exEN":"The skiers were warned to stay away from the steep slope because of avalanche danger.","exCN":"滑雪者被警告远离陡峭山坡，因为有雪崩危险。","extra":""},{"k":"ch1:53","id":53,"word":"terrain","phonetic":"/təˈreɪn/","pos":"n.","tag":"高频","meaning":"地形","root":"源自拉丁语 terrenum（大地）→ 地形","exEN":"The mountainous terrain made it difficult to build a railway through the region.","exCN":"多山的地形使得在该地区修建铁路十分困难。","extra":""},{"k":"ch1:54","id":54,"word":"landscape","phonetic":"/ˈlændskeɪp/","pos":"n.","tag":"核心","meaning":"风景，地貌","root":"land（陆地）+ -scape（表示性质、状况）→ 地貌","exEN":"The dramatic desert landscape attracted artists from around the world.","exCN":"这种壮观的沙漠地貌吸引了世界各地的艺术家。","extra":""},{"k":"ch1:55","id":55,"word":"continent","phonetic":"/ˈkɒntɪnənt/","pos":"n.","tag":"核心","meaning":"大陆；洲","root":"源自拉丁语 continens（连绵的土地）→ 大陆","exEN":"Australia is unique because it is both a country and an entire continent.","exCN":"澳大利亚很独特，因为它既是一个国家，又是一整块大陆。","extra":""},{"k":"ch1:56","id":56,"word":"cave","phonetic":"/keɪv/","pos":"n.","tag":"高频","meaning":"洞穴，山洞","root":"源自拉丁语 cava（空洞）→ 洞穴","exEN":"The explorers lit their torches before entering the dark limestone cave.","exCN":"探险者点燃火把，然后才进入漆黑的石灰岩洞穴。","extra":""},{"k":"ch1:57","id":57,"word":"cliff","phonetic":"/klɪf/","pos":"n.","tag":"高频","meaning":"悬崖，峭壁","root":"源自古英语 clif（岩石，陡坡）→ 悬崖","exEN":"They stood at the edge of the cliff, looking down at the waves crashing below.","exCN":"他们站在悬崖边缘，俯视下方翻腾的海浪。","extra":""},{"k":"ch1:58","id":58,"word":"glacier","phonetic":"/ˈɡlæsiə/","pos":"n.","tag":"高频","meaning":"冰河，冰川","root":"源自拉丁语 glacies（冰）→ 冰川","exEN":"Slowly moving glaciers carved deep valleys into the landscape over many centuries.","exCN":"缓慢移动的冰川经过许多世纪雕刻出深深的峡谷。","extra":""},{"k":"ch1:59","id":59,"word":"swamp","phonetic":"/swɒmp/","pos":"n.","tag":"高频","meaning":"沼泽，湿地","root":"起源不确定，可能来自日耳曼语（浸水的土地）→ 沼泽","exEN":"A wooden boardwalk let visitors cross the swamp without getting their feet wet.","exCN":"一条木板栈道让游客可以穿过沼泽而不会弄湿双脚。","extra":""},{"k":"ch1:60","id":60,"word":"delta","phonetic":"/ˈdeltə/","pos":"n.","tag":"高频","meaning":"三角洲","root":"源自希腊字母首个字母 Δ（三角形）→ 三角洲","exEN":"The Yangtze Delta is one of China's most economically developed regions.","exCN":"长江三角洲是中国经济最发达的地区之一。","extra":""},{"k":"ch1:61","id":61,"word":"plain","phonetic":"/pleɪn/","pos":"n.","tag":"核心","meaning":"平原","root":"源自拉丁语 planus（平坦的）→ 平原","exEN":"Vast wheat fields stretched across the flat plain as far as the eye could see.","exCN":"广阔的麦田穿过平坦的平原，一眼望不到边。","extra":""},{"k":"ch1:62","id":62,"word":"plateau","phonetic":"/ˈplætəʊ/","pos":"n.","tag":"高频","meaning":"高原","root":"源自法语 plateau（平盘）→ 高原","exEN":"The Tibetan Plateau rises so high that it is often called the roof of the world.","exCN":"青藏高原海拔如此之高，常被称为世界屋脊。","extra":""},{"k":"ch1:63","id":63,"word":"oasis","phonetic":"/əʊˈeɪsɪs/","pos":"n.","tag":"高频","meaning":"绿洲；宜人之地","root":"源自希腊语 oasis（绿洲）→ 沙漠中的水源地","exEN":"The small oasis offered a shaded resting spot for travelers crossing the dry desert.","exCN":"这片小绿洲为穿越干燥沙漠的旅人提供了一处阴凉歇脚地。","extra":""},{"k":"ch1:64","id":64,"word":"globe","phonetic":"/ɡləʊb/","pos":"n.","tag":"核心","meaning":"球体；地球仪；地球","root":"源自拉丁语 globus（球体）→ 地球","exEN":"The museum had a giant globe that showed all the world's shipping routes.","exCN":"博物馆里有一个巨大的地球仪，展示着全世界的航线。","extra":""},{"k":"ch1:65","id":65,"word":"hemisphere","phonetic":"/ˈhemɪsfɪə/","pos":"n.","tag":"高频","meaning":"半球","root":"hemi（半）+ sphere（球）→ 半球","exEN":"When it is summer in the northern hemisphere, it is winter in the southern.","exCN":"当北半球是夏季时，南半球就是冬季。","extra":""},{"k":"ch1:66","id":66,"word":"equator","phonetic":"/ɪˈkweɪtə/","pos":"n.","tag":"高频","meaning":"赤道","root":"源自拉丁语 aequare（使相等）→ 赤道（将地球平分）","exEN":"The sun blazed directly overhead as the ship crossed the equator.","exCN":"当船只越过赤道时，太阳直直地照在头顶上。","extra":""},{"k":"ch1:67","id":67,"word":"Arctic","phonetic":"/ˈɑːktɪk/","pos":"adj.","tag":"高频","meaning":"极冷的；北极的","root":"源自希腊语 arktikos（靠近大熊星座的；北方的）→ 北极的","exEN":"Polar bears are specially adapted to survive in the harsh Arctic environment.","exCN":"北极熊特别适应在严酷的北极环境中生存。","extra":""},{"k":"ch1:68","id":68,"word":"Antarctic","phonetic":"/ænˈtɑːktɪk/","pos":"adj.","tag":"高频","meaning":"南极的","root":"ant（对面的）+ arctic（北极）→ 北极的对面 → 南极","exEN":"The Antarctic ice sheet holds most of the planet's fresh water.","exCN":"南极冰盖储存着地球上大部分的淡水。","extra":""},{"k":"ch1:69","id":69,"word":"pole","phonetic":"/pəʊl/","pos":"n.","tag":"核心","meaning":"地极；截然相反的两极之一","root":"源自拉丁语 polus（轴的端点）→ 地极","exEN":"Scientists set up a temporary station near the South Pole to study the climate.","exCN":"科学家在南极附近设立了临时站研究气候。","extra":""},{"k":"ch1:70","id":70,"word":"polar","phonetic":"/ˈpəʊlə/","pos":"adj.","tag":"核心","meaning":"极地的，近极地的；对立的","root":"pole（极地）+ -ar（形容词后缀）→ 极地的","exEN":"The rapid warming of polar regions is alarming climate experts.","exCN":"极地地区的快速升温令气候专家感到担忧。","extra":""},{"k":"ch1:71","id":71,"word":"axis","phonetic":"/ˈæksɪs/","pos":"n.","tag":"高频","meaning":"轴，轴线","root":"源自拉丁语 axis（车轴；轴线）→ 轴线","exEN":"The Earth rotates around its tilted axis once every twenty-four hours.","exCN":"地球每二十四小时绕其倾斜的轴线自转一圈。","extra":""},{"k":"ch1:72","id":72,"word":"deteriorate","phonetic":"/dɪˈtɪəriəreɪt/","pos":"v.","tag":"核心","meaning":"恶化，变坏","root":"源自拉丁语 deterior（更差的）+ -ate（动词后缀）→ 恶化","exEN":"Air quality in the capital began to deteriorate as more factories opened.","exCN":"随着更多工厂开工，首都的空气质量开始恶化。","extra":""},{"k":"ch1:73","id":73,"word":"aggravate","phonetic":"/ˈæɡrəveɪt/","pos":"v.","tag":"核心","meaning":"加重，加剧，使恶化","root":"ag（加强意义）+ grav（重的）+ -ate（动词后缀）→ 加重","exEN":"Exhaust from cars may aggravate breathing problems in elderly people.","exCN":"汽车排放的废气可能加重老年人的呼吸问题。","extra":""},{"k":"ch1:74","id":74,"word":"degrade","phonetic":"/dɪˈɡreɪd/","pos":"v.","tag":"核心","meaning":"降解；降低身份；使恶化","root":"de（向下）+ grade（层级）→ 降级 → 退化","exEN":"Plastic bags take centuries to degrade naturally in the environment.","exCN":"塑料袋需要几个世纪才能在环境中自然降解。","extra":""},{"k":"ch1:75","id":75,"word":"upgrade","phonetic":"/ʌpˈɡreɪd/","pos":"v.","tag":"核心","meaning":"使升级；提高，改善","root":"up（向上）+ grade（层级）→ 升级","exEN":"They decided to upgrade the old power station to reduce air pollution.","exCN":"他们决定升级那座旧发电站以减少空气污染。","extra":""},{"k":"ch1:76","id":76,"word":"erode","phonetic":"/ɪˈrəʊd/","pos":"v.","tag":"核心","meaning":"侵蚀，腐蚀","root":"e（向外）+ rod（咬）+ e → 咬掉 → 侵蚀","exEN":"Constant rainfall will erode the topsoil on hills rebuilt without trees.","exCN":"持续降雨会侵蚀没有树木的山坡上的表层土壤。","extra":""},{"k":"ch1:77","id":77,"word":"Mediterranean","phonetic":"/ˌmedɪtəˈreɪniən/","pos":"adj.","tag":"识记","meaning":"地中海的；地中海地区的","root":"medi（中间）+ terra（陆地）→ 陆地之间的海 → 地中海","exEN":"The Mediterranean climate, with hot dry summers, attracts many tourists.","exCN":"夏季炎热干燥的地中海气候吸引了大量游客。","extra":""},{"k":"ch1:78","id":78,"word":"Atlantic","phonetic":"/ətˈlæntɪk/","pos":"adj.","tag":"识记","meaning":"大西洋的","root":"源自希腊语 Atlantikos（阿特拉斯之海）→ 大西洋","exEN":"The Atlantic trade winds helped early explorers cross the vast ocean.","exCN":"大西洋信风帮助早期探险者横渡这片广阔海洋。","extra":""},{"k":"ch1:79","id":79,"word":"Pacific","phonetic":"/pəˈsɪfɪk/","pos":"adj.","tag":"识记","meaning":"平静的，和平的；太平洋的","root":"源自拉丁语 pacificus（带来和平的）→ 太平洋（麦哲伦命名）","exEN":"The Pacific Ocean covers nearly one third of the Earth's total surface.","exCN":"太平洋几乎覆盖了地球总面积的三分之一。","extra":""},{"k":"ch1:80","id":80,"word":"ocean","phonetic":"/ˈəʊʃən/","pos":"n.","tag":"核心","meaning":"海洋；洋","root":"源自希腊语 ōkeanos（环绕大地的大河）→ 海洋","exEN":"The deep ocean remains one of the least explored areas on the planet.","exCN":"深海仍然是地球上探索最少的区域之一。","extra":""},{"k":"ch1:81","id":81,"word":"marine","phonetic":"/məˈriːn/","pos":"adj.","tag":"高频","meaning":"海生的，海洋的；海事的","root":"源自拉丁语 mare（海）→ 海洋的","exEN":"The government set up a protected area to preserve the region's marine life.","exCN":"政府设立保护区以保护该地区的海洋生物。","extra":""},{"k":"ch1:82","id":82,"word":"navigation","phonetic":"/ˌnævɪˈɡeɪʃən/","pos":"n.","tag":"高频","meaning":"航行；航海","root":"源自拉丁语 navis（船）+ agere（驾驶）→ 航海","exEN":"Modern ships rely on satellite navigation more than paper charts.","exCN":"现代船只更多地依赖卫星导航而非纸质海图。","extra":""},{"k":"ch1:83","id":83,"word":"gulf","phonetic":"/ɡʌlf/","pos":"n.","tag":"高频","meaning":"海湾","root":"源自希腊语 kolpos（怀抱；海湾）→ 海湾","exEN":"The gulf provides a natural harbor for fishing boats during bad weather.","exCN":"这个海湾在恶劣天气时为渔船提供了天然避风港。","extra":""},{"k":"ch1:84","id":84,"word":"beach","phonetic":"/biːtʃ/","pos":"n.","tag":"高频","meaning":"海滩，河滩","root":"源自古英语 bæce（溪流边的小石头）→ 海滩","exEN":"Children spent all afternoon building sand castles on the beach.","exCN":"孩子们整个下午都在海滩上堆沙堡。","extra":""},{"k":"ch1:85","id":85,"word":"coast","phonetic":"/kəʊst/","pos":"n.","tag":"核心","meaning":"海岸，海滨","root":"源自拉丁语 costa（肋骨；侧边）→ 海岸","exEN":"A series of wind farms was installed along the coast to generate clean power.","exCN":"沿岸安装了一系列风力发电机以产生清洁能源。","extra":""},{"k":"ch1:86","id":86,"word":"shore","phonetic":"/ʃɔː/","pos":"n.","tag":"高频","meaning":"岸，滨","root":"源自古英语 scora（岸）→ 岸","exEN":"They launched the lifeboat from the shore and rowed toward the sinking boat.","exCN":"他们从岸边放下救生艇，向正在下沉的船只划去。","extra":""},{"k":"ch1:87","id":87,"word":"tide","phonetic":"/taɪd/","pos":"n.","tag":"核心","meaning":"趋势，潮流；潮汐","root":"源自古英语 tīd（时间，时节）→ 潮汐","exEN":"The tide carried the drifting wood far up the beach during the night.","exCN":"潮水在夜间把漂流的木头冲到了海滩很远的地方。","extra":""},{"k":"ch1:88","id":88,"word":"current","phonetic":"/ˈkʌrənt/","pos":"n.","tag":"核心","meaning":"水流，潮流；电流；气流","root":"源自拉丁语 currere（跑）→ 流动 → 水流","exEN":"Swimmers were warned of a strong undercurrent that could pull them out to sea.","exCN":"游泳者被警告有一股强底流，可能将他们拖入外海。","extra":""},{"k":"ch1:89","id":89,"word":"brook","phonetic":"/brʊk/","pos":"n.","tag":"高频","meaning":"小河，溪","root":"源自古英语 brōc（小溪）→ 小河","exEN":"A clear brook runs through the middle of the village from the nearby hills.","exCN":"一条清澈的小溪从附近山上流过村庄中央。","extra":""},{"k":"ch1:90","id":90,"word":"stream","phonetic":"/striːm/","pos":"n.","tag":"核心","meaning":"小河，溪；流","root":"源自古英语 strēam（溪流）→ 溪","exEN":"They set up their tent beside a mountain stream to have fresh water nearby.","exCN":"他们在一条山间小溪旁搭起帐篷，以便就近取用淡水。","extra":""},{"k":"ch1:91","id":91,"word":"source","phonetic":"/sɔːs/","pos":"n.","tag":"核心","meaning":"河的源头；根源","root":"源自古法语 sourse（涌出）→ 源头","exEN":"The team followed the river all the way to its source high in the mountains.","exCN":"团队沿着河流一路走到它位于高山深处的源头。","extra":""},{"k":"ch1:92","id":92,"word":"shallow","phonetic":"/ˈʃæləʊ/","pos":"adj.","tag":"核心","meaning":"浅的；肤浅的，浅薄的","root":"源自古英语 sceald（浅的）→ 浅的","exEN":"The water near the shore was so shallow that we could walk out quite far.","exCN":"靠近岸边的水很浅，我们可以走出相当远。","extra":""},{"k":"ch1:93","id":93,"word":"superficial","phonetic":"/ˌsuːpəˈfɪʃəl/","pos":"adj.","tag":"高频","meaning":"表面的，表层的","root":"super（上）+ facies（面）+ -ial → 表面的","exEN":"The repair was only superficial; the deeper damage to the wall remained.","exCN":"修复只是表面的；墙壁内部更深的损坏依然存在。","extra":""},{"k":"ch1:94","id":94,"word":"flat","phonetic":"/flæt/","pos":"adj.","tag":"核心","meaning":"平坦的；扁平的；单调的","root":"源自古诺斯语 flatr（平坦的）→ 平坦的","exEN":"The team picked a flat and open area for their science camp.","exCN":"团队挑选了一块平坦开阔的区域作为科学营地。","extra":""},{"k":"ch1:95","id":95,"word":"smooth","phonetic":"/smuːð/","pos":"adj.","tag":"核心","meaning":"光滑的；平稳的；流畅的","root":"源自古英语 smōth（光滑的）→ 光滑的","exEN":"The river rocks had been worn smooth by thousands of years of running water.","exCN":"河中的石头被数千年流水磨得光滑。","extra":""},{"k":"ch1:96","id":96,"word":"rough","phonetic":"/rʌf/","pos":"adj.","tag":"核心","meaning":"粗糙的；粗略的","root":"源自古英语 rūh（粗糙的）→ 粗糙的","exEN":"The trail became rough and steep, forcing the hikers to slow their pace.","exCN":"小径变得崎岖陡峭，迫使徒步者放慢脚步。","extra":""},{"k":"ch1:97","id":97,"word":"sandy","phonetic":"/ˈsændi/","pos":"adj.","tag":"高频","meaning":"铺满沙的；含沙的","root":"sand（沙）+ -y（形容词后缀）→ 含沙的","exEN":"They cycled along a narrow sandy track that ran through the dunes.","exCN":"他们沿着一条穿过沙丘的窄沙土小路骑行。","extra":""},{"k":"ch1:98","id":98,"word":"stony","phonetic":"/ˈstəʊni/","pos":"adj.","tag":"高频","meaning":"石头的；多石的","root":"stone（石头）+ -y（形容词后缀）→ 多石的","exEN":"The farmer struggled to grow crops on the stony and unproductive land.","exCN":"这位农夫在那片多石的贫瘠土地上艰难耕种。","extra":""},{"k":"ch1:99","id":99,"word":"vertical","phonetic":"/ˈvɜːtɪkəl/","pos":"adj.","tag":"核心","meaning":"垂直的，直立的","root":"源自拉丁语 vertex（顶点；旋涡）→ 垂直","exEN":"The climber used ropes to safely ascend the nearly vertical cliff face.","exCN":"攀岩者用绳索安全地攀登近乎垂直的岩壁。","extra":""},{"k":"ch1:100","id":100,"word":"steep","phonetic":"/stiːp/","pos":"adj.","tag":"核心","meaning":"陡峭的，陡直的","root":"源自古英语 stēap（高的，陡的）→ 陡峭的","exEN":"Cars had to drive slowly down the steep road when it was covered with ice.","exCN":"路面结冰时，汽车不得不缓慢驶下陡坡。","extra":""},{"k":"ch1:101","id":101,"word":"parallel","phonetic":"/ˈpærəlel/","pos":"adj.","tag":"核心","meaning":"平行的；相似","root":"para（旁边）+ allelon（彼此）→ 平行的","exEN":"The two mountain ridges run almost perfectly parallel for dozens of miles.","exCN":"这两条山脊几乎完美平行地延伸数十英里。","extra":""},{"k":"ch1:102","id":102,"word":"narrow","phonetic":"/ˈnærəʊ/","pos":"adj.","tag":"核心","meaning":"狭窄的；有局限的","root":"源自古英语 nearu（狭窄的）→ 狭窄的","exEN":"Only one small boat could pass through the narrow channel at a time.","exCN":"一次只有一艘小船能通过这条狭窄的航道。","extra":""},{"k":"ch1:103","id":103,"word":"Oceania","phonetic":"/ˌəʊʃiˈɑːniə/","pos":"n.","tag":"识记","meaning":"大洋洲","root":"ocean（海洋）+ -ia（表示地方）→ 大洋洲","exEN":"Oceania consists of Australia, New Zealand, and many small Pacific islands.","exCN":"大洋洲包括澳大利亚、新西兰和许多太平洋小岛。","extra":""},{"k":"ch1:104","id":104,"word":"mainland","phonetic":"/ˈmeɪnlænd/","pos":"n.","tag":"核心","meaning":"大陆，本土","root":"main（主要的）+ land（陆地）→ 大陆","exEN":"Ferries run daily between the island and the mainland carrying supplies.","exCN":"渡船每天往返海岛和大陆之间运送物资。","extra":""},{"k":"ch1:105","id":105,"word":"peninsula","phonetic":"/pɪˈnɪnsjʊlə/","pos":"n.","tag":"高频","meaning":"半岛","root":"pen（几乎）+ insula（岛）→ 几乎是一个岛 → 半岛","exEN":"The Arabian Peninsula is bordered by the Red Sea on its western side.","exCN":"阿拉伯半岛西侧濒临红海。","extra":""},{"k":"ch1:106","id":106,"word":"climate","phonetic":"/ˈklaɪmɪt/","pos":"n.","tag":"核心","meaning":"气候；风气，思潮，环境","root":"源自希腊语 klima（倾斜；地区）→ 气候","exEN":"A warming climate is already affecting harvests in several farming regions.","exCN":"日益变暖的气候已经影响到几个农业区的收成。","extra":""},{"k":"ch1:107","id":107,"word":"weather","phonetic":"/ˈweðə/","pos":"n.","tag":"核心","meaning":"天气，气象","root":"源自古英语 weder（天气）→ 天气","exEN":"Due to bad weather, all outdoor sports activities were cancelled for the day.","exCN":"由于天气恶劣，当天所有户外体育活动都被取消。","extra":""},{"k":"ch1:108","id":108,"word":"meteorology","phonetic":"/ˌmiːtiəˈrɒlədʒi/","pos":"n.","tag":"识记","meaning":"气象学","root":"meteor（高处的事物）+ logy（学说）→ 气象学","exEN":"Advances in meteorology now allow forecasters to warn of storms days ahead.","exCN":"气象学的进步如今使得预报员可以提前数天预警暴风雨。","extra":""},{"k":"ch1:109","id":109,"word":"mild","phonetic":"/maɪld/","pos":"adj.","tag":"核心","meaning":"温和的；不严重的","root":"源自古英语 milde（温和的）→ 温和的","exEN":"The region has a mild spring that draws many outdoor painters every year.","exCN":"这个地区春季温和，每年都吸引许多户外写生画家。","extra":""},{"k":"ch1:110","id":110,"word":"heating","phonetic":"/ˈhiːtɪŋ/","pos":"n.","tag":"高频","meaning":"供暖；暖气装置","root":"heat（热）+ -ing（表示过程或设备）→ 供暖","exEN":"The old school was closed temporarily because its heating system failed.","exCN":"这所老学校因供暖系统故障而暂时关闭。","extra":""},{"k":"ch1:111","id":111,"word":"moderate","phonetic":"/ˈmɒdərɪt/","pos":"adj.","tag":"核心","meaning":"适度的；温和的；中等的","root":"源自拉丁语 moderatus（有节制的）→ 适度的","exEN":"The coastal area enjoys moderate temperatures all year thanks to the ocean breeze.","exCN":"受海风影响，这个沿海区域全年温度适中。","extra":""},{"k":"ch1:112","id":112,"word":"warm","phonetic":"/wɔːm/","pos":"adj.","tag":"核心","meaning":"温暖的","root":"源自古英语 wearm（温暖的）→ 温暖的","exEN":"A warm current from the south keeps the harbor free of ice in winter.","exCN":"一股来自南方的暖流使得港口在冬天不会结冰。","extra":""},{"k":"ch1:113","id":113,"word":"thermal","phonetic":"/ˈθɜːməl/","pos":"adj.","tag":"高频","meaning":"热量的","root":"源自希腊语 thermē（热）→ 热量的","exEN":"Birds use thermal columns of warm air to soar higher without flapping wings.","exCN":"鸟类借助热空气柱上升，无需扇动翅膀就能飞得更高。","extra":""},{"k":"ch1:114","id":114,"word":"tropics","phonetic":"/ˈtrɒpɪks/","pos":"n.","tag":"高频","meaning":"热带地区","root":"源自希腊语 tropikos（回转），与太阳回归线有关 → 热带","exEN":"Crops like bananas and pineapples grow well in the warm, wet tropics.","exCN":"香蕉和菠萝之类作物在温暖湿润的热带地区生长良好。","extra":""},{"k":"ch1:115","id":115,"word":"arid","phonetic":"/ˈærɪd/","pos":"adj.","tag":"高频","meaning":"干燥的，干旱的；枯燥的","root":"源自拉丁语 aridus（干燥的）→ 干旱的","exEN":"Only a few types of tough grass can survive in this arid environment.","exCN":"只有寥寥几种坚韧的草类能在这片干燥环境中生存。","extra":""},{"k":"ch1:116","id":116,"word":"moist","phonetic":"/mɔɪst/","pos":"adj.","tag":"高频","meaning":"潮湿的，湿润的","root":"源自古法语 moiste（潮湿的）→ 湿润的","exEN":"The forest floor stays cool and moist even during the hottest summer days.","exCN":"即使在最热的夏日，森林地面也保持凉爽湿润。","extra":""},{"k":"ch1:117","id":117,"word":"damp","phonetic":"/dæmp/","pos":"adj.","tag":"高频","meaning":"潮湿的，湿气重的","root":"源自中古低地德语 damp（蒸汽）→ 潮湿的","exEN":"The basement remained damp after the pipe leak, so we put a heater down there.","exCN":"管道泄漏后地下室里仍然很潮，我们在下面放了一台暖炉。","extra":""},{"k":"ch1:118","id":118,"word":"humid","phonetic":"/ˈhjuːmɪd/","pos":"adj.","tag":"高频","meaning":"潮湿的，湿热的","root":"源自拉丁语 humidus（湿的）→ 湿热的","exEN":"The humid air made even sitting still feel exhausting that afternoon.","exCN":"那天下午湿热的空气让人即使静静坐着也觉得疲惫。","extra":""},{"k":"ch1:119","id":119,"word":"snowy","phonetic":"/ˈsnəʊi/","pos":"adj.","tag":"高频","meaning":"下雪多的；被雪覆盖的","root":"snow（雪）+ -y（形容词后缀）→ 下雪多的","exEN":"The snowy peaks could be seen from the valley even in early summer.","exCN":"即使在初夏，从山谷也能望见白雪皑皑的山峰。","extra":""},{"k":"ch1:120","id":120,"word":"frost","phonetic":"/frɒst/","pos":"n.","tag":"高频","meaning":"霜；霜冻；严寒","root":"源自古英语 frost（霜）→ 霜冻","exEN":"A late frost in April damaged the early vegetable crops.","exCN":"四月的晚霜冻坏了早期蔬菜作物。","extra":""},{"k":"ch1:121","id":121,"word":"hail","phonetic":"/heɪl/","pos":"n.","tag":"高频","meaning":"雹，冰雹","root":"源自古英语 hægl（冰雹）→ 冰雹","exEN":"The sudden burst of hail cracked the greenhouse windows and flattened the seedlings.","exCN":"突然降下的冰雹打裂了温室玻璃，压倒了幼苗。","extra":""},{"k":"ch1:122","id":122,"word":"thaw","phonetic":"/θɔː/","pos":"v.","tag":"高频","meaning":"解冻，融解，融化","root":"源自古英语 þawian（融化）→ 解冻","exEN":"After a long winter, the rivers slowly began to thaw in early March.","exCN":"漫长的冬天过后，河流在三月初开始慢慢解冻。","extra":""},{"k":"ch1:123","id":123,"word":"chill","phonetic":"/tʃɪl/","pos":"n.","tag":"高频","meaning":"寒冷；害怕","root":"源自古英语 cele（寒冷）→ 寒冷","exEN":"A sudden chill filled the room when the window blew open at night.","exCN":"夜里窗户被风吹开时，一阵寒意充满了房间。","extra":""},{"k":"ch1:124","id":124,"word":"freeze","phonetic":"/friːz/","pos":"v.","tag":"核心","meaning":"结冰；霜冻；严寒期","root":"源自古英语 frēosan（结冰）→ 结冰","exEN":"The pond will freeze over if the night temperature keeps falling at this rate.","exCN":"如果夜间温度按这个速度继续下降，池塘就要结冰了。","extra":""},{"k":"ch1:125","id":125,"word":"frigid","phonetic":"/ˈfrɪdʒɪd/","pos":"adj.","tag":"高频","meaning":"寒冷的","root":"源自拉丁语 frigidus（寒冷的）→ 寒冷的","exEN":"Explorers wrapped themselves in thick coats to bear the frigid polar wind.","exCN":"探险者裹着厚外套忍受极地的寒风。","extra":""},{"k":"ch1:126","id":126,"word":"tremble","phonetic":"/ˈtrembəl/","pos":"v.","tag":"高频","meaning":"战栗，颤抖","root":"源自拉丁语 tremulus（颤抖的）→ 战栗","exEN":"Leaves on the tree began to tremble just before the earthquake struck.","exCN":"就在地震来临前，树上的叶子开始颤抖。","extra":""},{"k":"ch1:127","id":127,"word":"shiver","phonetic":"/ˈʃɪvə/","pos":"v.","tag":"高频","meaning":"颤抖，哆嗦，发抖","root":"起源不确定，可能与中古英语 chiveren（发抖）相关 → 发抖","exEN":"The little dog sat in the cold rain and shivered until we brought it inside.","exCN":"小狗坐在冰冷的雨中发抖，直到我们把它抱进屋里。","extra":""},{"k":"ch1:128","id":128,"word":"thunder","phonetic":"/ˈθʌndə/","pos":"n.","tag":"高频","meaning":"雷；雷声","root":"源自古英语 þunor（雷声）→ 雷","exEN":"A loud clap of thunder woke the whole campsite in the early morning.","exCN":"清晨一声响雷把整个营地都吵醒了。","extra":""},{"k":"ch1:129","id":129,"word":"lightning","phonetic":"/ˈlaɪtnɪŋ/","pos":"n.","tag":"高频","meaning":"闪电","root":"lighten（发光）+ -ing（名词后缀）→ 闪电","exEN":"A flash of lightning split the dark sky in two for just a brief moment.","exCN":"一道闪电霎时间把黑暗的天空劈成两半。","extra":""},{"k":"ch1:130","id":130,"word":"stormy","phonetic":"/ˈstɔːmi/","pos":"adj.","tag":"高频","meaning":"有暴风雨的；争吵激烈的；波涛汹涌的","root":"storm（暴风雨）+ -y（形容词后缀）→ 有暴风雨的","exEN":"The ship rocked heavily as the stormy sea tossed it from side to side.","exCN":"波涛汹涌的海面把船猛烈地左右摇晃。","extra":""},{"k":"ch1:131","id":131,"word":"downpour","phonetic":"/ˈdaʊnpɔː/","pos":"n.","tag":"高频","meaning":"倾盆大雨","root":"down（向下）+ pour（倾倒）→ 倾盆大雨","exEN":"The sudden downpour flooded the streets within minutes.","exCN":"突如其来的倾盆大雨几分钟内就淹了街道。","extra":""},{"k":"ch1:132","id":132,"word":"rainfall","phonetic":"/ˈreɪnfɔːl/","pos":"n.","tag":"高频","meaning":"降雨量","root":"rain（雨）+ fall（降落）→ 降雨量","exEN":"Heavy rainfall in the mountains led to a rapid rise in the river level.","exCN":"山区强降雨导致河水位迅速上涨。","extra":""},{"k":"ch1:133","id":133,"word":"sprinkle","phonetic":"/ˈsprɪŋkl/","pos":"v.","tag":"高频","meaning":"撒，洒；下小雨","root":"起源不确定，可能与中古荷兰语 sprenkelen（洒）相关 → 洒","exEN":"Light rain began to sprinkle the windows as we sat by the fireplace.","exCN":"我们坐在壁炉旁时，小雨开始淅淅沥沥地打在窗户上。","extra":""},{"k":"ch1:134","id":134,"word":"rainbow","phonetic":"/ˈreɪnbəʊ/","pos":"n.","tag":"高频","meaning":"虹，彩虹","root":"rain（雨）+ bow（弓）→ 彩虹","exEN":"A bright double rainbow appeared across the valley after the storm passed.","exCN":"暴风雨过后，一道明亮的双彩虹横跨山谷出现。","extra":""},{"k":"ch1:135","id":135,"word":"shower","phonetic":"/ˈʃaʊə/","pos":"n.","tag":"高频","meaning":"阵雨；淋浴","root":"源自古英语 scūr（阵雨）→ 阵雨","exEN":"We waited in the tent for the shower to pass before hiking again.","exCN":"我们在帐篷里等阵雨过去再继续徒步。","extra":""},{"k":"ch1:136","id":136,"word":"Celsius","phonetic":"/ˈselsiəs/","pos":"adj.","tag":"识记","meaning":"摄氏的","root":"以瑞典科学家 Anders Celsius 命名 → 摄氏","exEN":"Water boils at one hundred degrees Celsius under normal air pressure.","exCN":"在正常气压下，水在100摄氏度沸腾。","extra":""},{"k":"ch1:137","id":137,"word":"temperature","phonetic":"/ˈtemprɪtʃə/","pos":"n.","tag":"核心","meaning":"气温；体温；温度","root":"源自拉丁语 temperatura（恰当比例混合）→ 温度","exEN":"The temperature dropped sharply after sunset, so we lit a campfire.","exCN":"日落之后温度骤降，我们便点燃了篝火。","extra":""},{"k":"ch1:138","id":138,"word":"forecast","phonetic":"/ˈfɔːkɑːst/","pos":"n.","tag":"核心","meaning":"预测，预报","root":"fore（前，先）+ cast（扔）→ 提前抛出的信息 → 预报","exEN":"According to the forecast, clear skies will return to the coast by Friday.","exCN":"根据预报，周五之前沿海地区将恢复晴好天气。","extra":""},{"k":"ch1:139","id":139,"word":"peak","phonetic":"/piːk/","pos":"n.","tag":"核心","meaning":"山峰；顶点","root":"起源不确定，可能来自中古低地德语 pēk（尖端）→ 山峰","exEN":"They reached the peak just as the sun rose over the horizon.","exCN":"他们正好在太阳从地平线升起时到达了山顶。","extra":""},{"k":"ch1:140","id":140,"word":"mount","phonetic":"/maʊnt/","pos":"v.","tag":"核心","meaning":"渐渐增加；爬上，登上","root":"源自拉丁语 mons（山）→ 登上；增加","exEN":"The team slowly mounted the rocky slope as the wind grew stronger.","exCN":"队伍缓慢地爬上岩石山坡，风也越来越大。","extra":""},{"k":"ch1:141","id":141,"word":"mountain","phonetic":"/ˈmaʊntɪn/","pos":"n.","tag":"核心","meaning":"山，山岳，高山","root":"源自拉丁语 mons（山）→ 山","exEN":"Snow on the mountain top had not melted even by late June.","exCN":"即使到了六月末，山顶的积雪也没有融化。","extra":""},{"k":"ch1:142","id":142,"word":"range","phonetic":"/reɪndʒ/","pos":"n.","tag":"核心","meaning":"山脉；范围","root":"源自古法语 range（排，行）→ 山脉；范围","exEN":"The long mountain range stretches across the entire northern part of the country.","exCN":"这条长长的山脉横贯整个国家的北部。","extra":""},{"k":"ch1:143","id":143,"word":"ridge","phonetic":"/rɪdʒ/","pos":"n.","tag":"高频","meaning":"山脊，山脉","root":"源自古英语 hrycg（背脊）→ 山脊","exEN":"They walked along a narrow ridge with steep drops on both sides.","exCN":"他们沿着一条两边都是陡坡的狭窄山脊行走。","extra":""},{"k":"ch1:144","id":144,"word":"slope","phonetic":"/sləʊp/","pos":"n.","tag":"核心","meaning":"山坡；斜坡","root":"源自古英语 āslopen（滑离）→ 斜坡","exEN":"The ski school uses the gentler slope for beginners to practise.","exCN":"滑雪学校用较平缓的坡给初学者练习。","extra":""},{"k":"ch1:145","id":145,"word":"valley","phonetic":"/ˈvæli/","pos":"n.","tag":"核心","meaning":"山谷，溪谷","root":"源自拉丁语 vallis（山谷）→ 山谷","exEN":"The green valley below was covered with orchards and small farms.","exCN":"下方的翠绿山谷遍布果园和小型农场。","extra":""},{"k":"ch1:146","id":146,"word":"hillside","phonetic":"/ˈhɪlsaɪd/","pos":"n.","tag":"高频","meaning":"山腰，山坡","root":"hill（小山）+ side（侧面）→ 山腰","exEN":"Sheep grazed peacefully on the sunny hillside above the village.","exCN":"绵羊在村庄上方阳光明媚的山坡上安静地吃草。","extra":""},{"k":"ch1:147","id":147,"word":"overlook","phonetic":"/ˌəʊvəˈlʊk/","pos":"v.","tag":"核心","meaning":"俯瞰，远眺；未注意到","root":"over（在上）+ look（看）→ 从上面往下看 → 俯瞰","exEN":"The viewing platform lets visitors overlook the entire lake and its islands.","exCN":"观景台让游客可以俯瞰整个湖泊及其岛屿。","extra":""},{"k":"ch1:148","id":148,"word":"southern","phonetic":"/ˈsʌðən/","pos":"adj.","tag":"核心","meaning":"南部的；南方的","root":"south（南）+ -ern（表示方向的形容词后缀）→ 南部的","exEN":"The southern region of the island gets more sunshine than the north.","exCN":"岛屿的南部地区比北部日照更充足。","extra":""},{"k":"ch1:149","id":149,"word":"southeast","phonetic":"/ˌsaʊθˈiːst/","pos":"n.","tag":"高频","meaning":"东南方；东南部","root":"south（南）+ east（东）→ 东南方","exEN":"The storm is currently moving toward the southeast at about fifteen miles per hour.","exCN":"暴风雨目前正以大约每小时十五英里的速度向东南方向移动。","extra":""},{"k":"ch1:150","id":150,"word":"southwest","phonetic":"/ˌsaʊθˈwest/","pos":"n.","tag":"高频","meaning":"西南方；西南部","root":"south（南）+ west（西）→ 西南方","exEN":"The southwest monsoon brings heavy rain to this coastal town every summer.","exCN":"每年夏天，西南季风都会给这个沿海小镇带来大量降雨。","extra":""},{"k":"ch1:151","id":151,"word":"northeast","phonetic":"/ˌnɔːθˈiːst/","pos":"n.","tag":"高频","meaning":"东北方；东北部","root":"north（北）+ east（东）→ 东北方","exEN":"Winds from the northeast pushed the thick fog out to sea by late morning.","exCN":"来自东北方向的风在上午快结束时将浓雾推向外海。","extra":""},{"k":"ch1:152","id":152,"word":"northwest","phonetic":"/ˌnɔːθˈwest/","pos":"n.","tag":"高频","meaning":"西北方；西北部","root":"north（北）+ west（西）→ 西北方","exEN":"The northwest coast is famous for its rugged cliffs and winding trails.","exCN":"西北海岸以崎岖的悬崖和蜿蜒的小径闻名。","extra":""},{"k":"ch1:153","id":153,"word":"eastern","phonetic":"/ˈiːstən/","pos":"adj.","tag":"核心","meaning":"东部的；东方的","root":"east（东）+ -ern（形容词后缀）→ 东部的","exEN":"The eastern part of the forest is home to a large deer population.","exCN":"这片森林的东部有大量鹿群栖息。","extra":""},{"k":"ch1:154","id":154,"word":"oriental","phonetic":"/ˌɔːriˈentl/","pos":"adj.","tag":"高频","meaning":"东方的（尤指中国和日本的）","root":"源自拉丁语 oriens（升起；东方）→ 东方的","exEN":"The gallery displays a fine collection of oriental ceramics from various dynasties.","exCN":"这座画廊展出来自不同朝代的精美东方陶瓷藏品。","extra":""},{"k":"ch1:155","id":155,"word":"inevitable","phonetic":"/ɪnˈevɪtəbl/","pos":"adj.","tag":"核心","meaning":"不可避免的，必然的","root":"in（不）+ evitable（可避免的）→ 不可避免的","exEN":"With rising sea levels, some erosion of coastal roads is almost inevitable.","exCN":"随着海平面上升，沿海道路遭到一些侵蚀几乎是不可避免的。","extra":""},{"k":"ch1:156","id":156,"word":"irreversible","phonetic":"/ˌɪrɪˈvɜːsɪbəl/","pos":"adj.","tag":"高频","meaning":"不可逆转的；不可挽回的","root":"ir（不）+ re（回）+ vers（转）+ -ible（可……的）→ 不可逆转的","exEN":"The desertification of this once green land now seems irreversible.","exCN":"这片曾经绿意盎然的土地的荒漠化如今似乎不可逆转。","extra":""},{"k":"ch1:157","id":157,"word":"irregularly","phonetic":"/ɪˈreɡjʊləli/","pos":"adv.","tag":"高频","meaning":"不规则地；不合常规地","root":"ir（不）+ regular（规律的）+ -ly（副词后缀）→ 不规则地","exEN":"Rain falls very irregularly across the region, causing frequent dry spells.","exCN":"整个地区的降雨非常不规律，导致频繁出现干旱期。","extra":""},{"k":"ch1:158","id":158,"word":"inappropriate","phonetic":"/ˌɪnəˈprəʊpriɪt/","pos":"adj.","tag":"核心","meaning":"不合适的","root":"in（不）+ appropriate（恰当的）→ 不合适的","exEN":"The plan to build a factory so close to the river was clearly inappropriate.","exCN":"在如此靠近河流的地方建工厂的计划明显不合适。","extra":""},{"k":"ch1:159","id":159,"word":"abnormal","phonetic":"/æbˈnɔːməl/","pos":"adj.","tag":"核心","meaning":"不正常的，反常的；变态的","root":"ab（不）+ normal（正常的）→ 不正常的","exEN":"Scientists were worried by the abnormal warming of the sea surface this spring.","exCN":"科学家对今春海面异常升温感到担忧。","extra":""},{"k":"ch1:160","id":160,"word":"sediment","phonetic":"/ˈsedɪmənt/","pos":"n.","tag":"高频","meaning":"沉淀物；沉积物","root":"源自拉丁语 sedere（坐下；沉淀）→ 沉淀物","exEN":"The river delta was formed by sediment carried downstream over many centuries.","exCN":"这条河流三角洲是由数世纪不断带往下游的沉积物形成的。","extra":""},{"k":"ch1:161","id":161,"word":"silt","phonetic":"/sɪlt/","pos":"n.","tag":"高频","meaning":"淤泥，泥沙","root":"起源不确定，可能与中古低地德语 sulte（盐碱地）相关 → 淤泥","exEN":"The removal of trees from the river bank has allowed more silt to enter the channel.","exCN":"河岸树木被清除后，更多泥沙进入了河道。","extra":""},{"k":"ch1:162","id":162,"word":"muddy","phonetic":"/ˈmʌdi/","pos":"adj.","tag":"高频","meaning":"泥泞的；浑浊的","root":"mud（泥）+ -y（形容词后缀）→ 泥泞的","exEN":"After the heavy rain, the path became so muddy that we had to turn back.","exCN":"大雨过后，小路变得泥泞不堪，我们只好原路返回。","extra":""},{"k":"ch1:163","id":163,"word":"clay","phonetic":"/kleɪ/","pos":"n.","tag":"高频","meaning":"黏土，陶土","root":"源自古英语 clǣg（黏土）→ 黏土","exEN":"Local artists dig clay from the riverbank to make traditional pottery.","exCN":"当地艺人从河岸挖取黏土制作传统陶器。","extra":""},{"k":"ch1:164","id":164,"word":"dirt","phonetic":"/dɜːt/","pos":"n.","tag":"核心","meaning":"污垢，灰尘；泥土","root":"源自古诺斯语 drit（排泄物）→ 泥土；污垢","exEN":"The children returned from the forest hike with dirt on their boots and smiles.","exCN":"孩子们从森林徒步回来，靴子上沾满泥土，脸上带着笑容。","extra":""},{"k":"ch1:165","id":165,"word":"rural","phonetic":"/ˈrʊərəl/","pos":"adj.","tag":"核心","meaning":"农村的，乡村的；田园的","root":"源自拉丁语 rus（乡村）+ -al（形容词后缀）→ 农村的","exEN":"Internet access in many rural areas remains slower than in large cities.","exCN":"许多农村地区的网络连接仍然比大城市慢。","extra":""},{"k":"ch1:166","id":166,"word":"suburb","phonetic":"/ˈsʌbɜːb/","pos":"n.","tag":"核心","meaning":"郊区，郊外，近郊","root":"sub（接近）+ urb（城市）→ 城市附近的区域 → 郊区","exEN":"The factory was built on former farmland on the edge of the northern suburb.","exCN":"工厂建在北郊边缘以前的农田上。","extra":""},{"k":"ch1:167","id":167,"word":"outskirts","phonetic":"/ˈaʊtskɜːts/","pos":"n.","tag":"高频","meaning":"郊区，市郊","root":"out（外）+ skirt（边缘）+ -s → 外围地区 → 市郊","exEN":"The nature reserve lies on the outskirts of the capital, about an hour away.","exCN":"自然保护区位于首都郊外约一小时路程处。","extra":""},{"k":"ch1:168","id":168,"word":"remote","phonetic":"/rɪˈməʊt/","pos":"adj.","tag":"核心","meaning":"遥远的；偏僻的；疏远的","root":"源自拉丁语 remotus（移开的；遥远的）→ 遥远的","exEN":"The research team set up instruments at several remote mountain stations.","exCN":"研究团队在好几个偏远的山区站点安装了仪器。","extra":""},{"k":"ch1:169","id":169,"word":"desolate","phonetic":"/ˈdesələt/","pos":"adj.","tag":"高频","meaning":"荒凉的","root":"源自拉丁语 desolatus（被遗弃的）→ 荒凉的","exEN":"The old mining town was now completely desolate, with only wind and dust.","exCN":"这座旧矿镇如今已完全荒凉，只剩风声和尘土。","extra":""},{"k":"ch1:170","id":170,"word":"distant","phonetic":"/ˈdɪstənt/","pos":"adj.","tag":"核心","meaning":"疏远的；遥远的","root":"dis（分开）+ stant（站立）→ 站得分开的 → 遥远的","exEN":"We could hear the distant sound of waterfalls as we reached the forest edge.","exCN":"我们到达森林边缘时可以听见远处瀑布的声音。","extra":""},{"k":"ch1:171","id":171,"word":"adjacent","phonetic":"/əˈdʒeɪsənt/","pos":"adj.","tag":"高频","meaning":"邻近的，毗连的","root":"源自拉丁语 adjacere（躺在附近）→ 邻近的","exEN":"The hotel and its adjacent nature trail attract many bird watchers.","exCN":"酒店和它邻近的自然小径吸引了许多观鸟者。","extra":""},{"k":"ch1:172","id":172,"word":"toxic","phonetic":"/ˈtɒksɪk/","pos":"adj.","tag":"核心","meaning":"有毒的","root":"源自希腊语 toxon（弓；毒箭）→ 有毒的","exEN":"The lake was closed to fishing after tests showed toxic levels of mercury.","exCN":"检验显示湖泊汞含量有毒后，该湖被禁止捕鱼。","extra":""},{"k":"ch1:173","id":173,"word":"pollution","phonetic":"/pəˈljuːʃən/","pos":"n.","tag":"核心","meaning":"污染","root":"pollute（弄脏）+ -ion（名词后缀）→ 污染","exEN":"Oil spills at sea are among the most difficult types of pollution to clean up.","exCN":"海上石油泄漏是最难清理的污染类型之一。","extra":""},{"k":"ch1:174","id":174,"word":"pollutant","phonetic":"/pəˈljuːtənt/","pos":"n.","tag":"核心","meaning":"污染物质","root":"pollute（污染）+ -ant（表示物质的名词后缀）→ 污染物","exEN":"Researchers have identified several harmful pollutants in the city's drinking water.","exCN":"研究人员在该市饮用水中鉴定出了好几种有害污染物。","extra":""},{"k":"ch1:175","id":175,"word":"contaminate","phonetic":"/kənˈtæmɪneɪt/","pos":"v.","tag":"核心","meaning":"弄脏，污染","root":"con（共同）+ tam（接触）+ in（里面）+ -ate（动词后缀）→ 污染","exEN":"Heavy rain washed the chemical waste into the river, contaminating the fish.","exCN":"大雨把化工废料冲进河中，污染了鱼类。","extra":""},{"k":"ch1:176","id":176,"word":"geology","phonetic":"/dʒiˈɒlədʒi/","pos":"n.","tag":"高频","meaning":"地质学；地质状况","root":"geo（地球）+ logy（学说）→ 地质学","exEN":"Understanding the geology of the region helps engineers design safer tunnels.","exCN":"了解该地区的地质状况有助于工程师设计更安全的隧道。","extra":""},{"k":"ch1:177","id":177,"word":"border","phonetic":"/ˈbɔːdə/","pos":"n.","tag":"核心","meaning":"边界；边界地区；镶边","root":"源自古法语 bordure（边缘）→ 边界","exEN":"The border between the two countries runs through thick forests and high ridges.","exCN":"两国之间的边界穿过茂密的森林和高高的山脊。","extra":""},{"k":"ch1:178","id":178,"word":"margin","phonetic":"/ˈmɑːdʒɪn/","pos":"n.","tag":"核心","meaning":"边缘；页边空白；余地","root":"源自拉丁语 margo（边缘）→ 边缘；余地","exEN":"There is little margin left for error in the final week of the project.","exCN":"在项目最后一周几乎没有出错的余地了。","extra":""},{"k":"ch1:179","id":179,"word":"fringe","phonetic":"/frɪndʒ/","pos":"n.","tag":"高频","meaning":"边缘；刘海儿","root":"源自拉丁语 fimbria（流苏；边缘）→ 边缘","exEN":"The town sits on the fringe of the vast desert, where dust storms are common.","exCN":"小镇坐落在大沙漠边缘，那里沙尘暴很常见。","extra":""},{"k":"ch1:180","id":180,"word":"plate","phonetic":"/pleɪt/","pos":"n.","tag":"高频","meaning":"板块；盘","root":"源自希腊语 platus（扁平的）→ 平板 → 板块","exEN":"The collision of two massive plates gave rise to the great mountain belt.","exCN":"两块巨大板块的碰撞造就了这条宏伟的山脉带。","extra":""},{"k":"ch1:181","id":181,"word":"debris","phonetic":"/ˈdebriː/","pos":"n.","tag":"高频","meaning":"碎片，残骸","root":"源自法语 débris（碎片）→ 残骸","exEN":"Emergency workers spent days clearing the debris after the landslide.","exCN":"紧急救援人员花了数天清理滑坡后的碎石残骸。","extra":""},{"k":"ch1:182","id":182,"word":"crack","phonetic":"/kræk/","pos":"v.","tag":"高频","meaning":"破裂；发出爆裂声","root":"源自古英语 cracian（发出爆裂声）→ 破裂","exEN":"A thin crack in the dam wall had engineers working through the night.","exCN":"堤坝上一条细小的裂缝令工程师们连夜抢修。","extra":""},{"k":"ch1:183","id":183,"word":"gap","phonetic":"/ɡæp/","pos":"n.","tag":"核心","meaning":"缺口，裂缝；差距；空白","root":"源自古诺斯语 gap（开口）→ 缺口","exEN":"The study found a wide gap between the predicted and actual rainfall totals.","exCN":"研究发现预测降雨总量与实际降雨总量之间存在巨大差距。","extra":""},{"k":"ch1:184","id":184,"word":"splendid","phonetic":"/ˈsplendɪd/","pos":"adj.","tag":"核心","meaning":"极好的；壮观的","root":"源自拉丁语 splendidus（辉煌的）→ 壮观的","exEN":"From the flight window, we had a splendid view of the snow-capped volcanoes.","exCN":"从飞机窗口，我们看到了白雪覆盖的火山壮丽景色。","extra":""},{"k":"ch1:185","id":185,"word":"grand","phonetic":"/ɡrænd/","pos":"adj.","tag":"核心","meaning":"宏大的；豪华的，宏伟的；极好的","root":"源自拉丁语 grandis（巨大的）→ 宏伟的","exEN":"The grand canyon stretched out below us, carved over millions of years.","exCN":"宏伟的大峡谷在我们下方延伸，是历经数百万年雕刻而成。","extra":""},{"k":"ch1:186","id":186,"word":"magnificent","phonetic":"/mæɡˈnɪfɪsənt/","pos":"adj.","tag":"核心","meaning":"壮丽的，宏伟的；令人印象深刻的","root":"源自拉丁语 magnificus（伟大的）→ 壮丽的","exEN":"The magnificent waterfall drops three hundred metres straight into the pool below.","exCN":"壮丽的瀑布直落三百米坠入下方的水潭。","extra":""},{"k":"ch1:187","id":187,"word":"super","phonetic":"/ˈsuːpə/","pos":"adj.","tag":"核心","meaning":"超级的，极好的","root":"源自拉丁语 super（上等的）→ 极好的","exEN":"The guide showed us a super spot on the hillside to watch the sunrise.","exCN":"向导指给我们山坡上一个绝佳地点观看日出。","extra":""},{"k":"ch1:188","id":188,"word":"interesting","phonetic":"/ˈɪntrɪstɪŋ/","pos":"adj.","tag":"核心","meaning":"有趣的；引人入胜的","root":"interest（兴趣）+ -ing（形容词后缀）→ 有趣的","exEN":"It is interesting to compare the different weather patterns of these two regions.","exCN":"比较这两个地区不同的天气模式很有趣。","extra":""},{"k":"ch1:189","id":189,"word":"dramatic","phonetic":"/drəˈmætɪk/","pos":"adj.","tag":"核心","meaning":"戏剧的；引人注目的","root":"源自希腊语 dramatikos（有关戏剧的）→ 引人注目的","exEN":"The beach has undergone dramatic changes after last winter's series of storms.","exCN":"经历了去年冬天一连串风暴后，这片海滩发生了显著变化。","extra":""},{"k":"ch1:190","id":190,"word":"wilderness","phonetic":"/ˈwɪldənɪs/","pos":"n.","tag":"高频","meaning":"荒野","root":"wild（野生的）+ -ness（表示地带的词缀）→ 荒野","exEN":"They spent ten days hiking through a vast wilderness of frozen lakes and forests.","exCN":"他们花了十天在满是冻湖和森林的广阔荒野中徒步。","extra":""},{"k":"ch1:191","id":191,"word":"desert","phonetic":"/ˈdezət/","pos":"n.","tag":"核心","meaning":"沙漠","root":"源自拉丁语 desertum（被遗弃的地方）→ 沙漠","exEN":"Cacti have shallow roots that spread wide to absorb rare desert rains.","exCN":"仙人掌有浅浅的宽根，以吸收沙漠中罕见的雨水。","extra":""},{"k":"ch1:192","id":192,"word":"deforest","phonetic":"/diːˈfɒrɪst/","pos":"v.","tag":"识记","meaning":"毁掉森林","root":"de（除去）+ forest（森林）→ 毁林","exEN":"Large areas were deforested to make room for coffee and palm oil farms.","exCN":"大片森林被砍伐，为咖啡和棕榈油种植园腾出空间。","extra":""},{"k":"ch1:193","id":193,"word":"barren","phonetic":"/ˈbærən/","pos":"adj.","tag":"高频","meaning":"贫瘠的，荒芜的；不结果实的","root":"源自古法语 baraigne（不能生育的）→ 贫瘠的","exEN":"Years of mining left the landscape barren and empty of plant life.","exCN":"多年采矿使这片土地贫瘠荒芜，寸草不生。","extra":""},{"k":"ch1:194","id":194,"word":"fertile","phonetic":"/ˈfɜːtaɪl/","pos":"adj.","tag":"高频","meaning":"肥沃的，富饶的","root":"源自拉丁语 fertilis（结果实的）→ 肥沃的","exEN":"The volcanic soil around the mountain is dark and extremely fertile.","exCN":"火山周围的土壤呈黑色，极其肥沃。","extra":""},{"k":"ch1:195","id":195,"word":"fertilise","phonetic":"/ˈfɜːtɪlaɪz/","pos":"v.","tag":"高频","meaning":"施肥于","root":"fertile（肥沃的）+ -ise（动词后缀）→ 施肥","exEN":"Farmers fertilise the rice fields before the rainy season arrives.","exCN":"农民在雨季来临前给稻田施肥。","extra":""},{"k":"ch1:196","id":196,"word":"solar","phonetic":"/ˈsəʊlə/","pos":"adj.","tag":"核心","meaning":"太阳的，日光的","root":"源自拉丁语 sol（太阳）+ -ar（形容词后缀）→ 太阳的","exEN":"The village now relies on solar panels to power its small school and clinic.","exCN":"这个村庄现在靠太阳能板给小型学校和诊所供电。","extra":""},{"k":"ch1:197","id":197,"word":"lunar","phonetic":"/ˈluːnə/","pos":"adj.","tag":"核心","meaning":"月亮的，月球的","root":"源自拉丁语 luna（月亮）+ -ar（形容词后缀）→ 月亮的","exEN":"The lunar surface is covered with craters, stones and fine grey dust.","exCN":"月球表面布满陨石坑、石块和灰色细尘。","extra":""},{"k":"ch1:198","id":198,"word":"calendar","phonetic":"/ˈkælɪndə/","pos":"n.","tag":"核心","meaning":"日历；历法","root":"源自拉丁语 kalendarium（账本；记录）→ 日历","exEN":"The farmer marked the planting dates on a large paper calendar in the barn.","exCN":"农夫在谷仓里的大纸日历上标记了播种日期。","extra":""},{"k":"ch1:199","id":199,"word":"sunrise","phonetic":"/ˈsʌnraɪz/","pos":"n.","tag":"核心","meaning":"日出","root":"sun（太阳）+ rise（升起）→ 日出","exEN":"The fishermen set out on their boats just before sunrise each day.","exCN":"渔民每天在日出前就乘小船出海。","extra":""},{"k":"ch1:200","id":200,"word":"sunset","phonetic":"/ˈsʌnset/","pos":"n.","tag":"核心","meaning":"日落","root":"sun（太阳）+ set（落下）→ 日落","exEN":"We packed up our cameras after the last light of the sunset faded.","exCN":"日落的最后一道光消失后，我们收起了相机。","extra":""},{"k":"ch1:201","id":201,"word":"eclipse","phonetic":"/ɪˈklɪps/","pos":"n.","tag":"高频","meaning":"日食；月食","root":"源自希腊语 ekleipsis（放弃；消失）→ 日/月食","exEN":"Hundreds of people gathered with special glasses to watch the solar eclipse.","exCN":"数百人戴着特制眼镜聚集在一起观看日食。","extra":""},{"k":"ch1:202","id":202,"word":"dusk","phonetic":"/dʌsk/","pos":"n.","tag":"核心","meaning":"黄昏，傍晚","root":"源自古英语 dox（暗色）→ 黄昏","exEN":"Bats start to hunt for insects over the river shortly after dusk.","exCN":"黄昏刚过，蝙蝠就开始在河面上捕食昆虫。","extra":""},{"k":"ch1:203","id":203,"word":"heaven","phonetic":"/ˈhevn/","pos":"n.","tag":"核心","meaning":"天堂；极乐之地；天空","root":"源自古英语 heofon（天；天堂）→ 天空；天堂","exEN":"The peak rose into a clear blue heaven without a single cloud in sight.","exCN":"山顶耸入清澈的蓝天，看不到一丝云彩。","extra":""},{"k":"ch1:204","id":204,"word":"paradise","phonetic":"/ˈpærədaɪs/","pos":"n.","tag":"核心","meaning":"天堂；乐园，福地","root":"源自波斯语 pairidaeza（围墙花园）→ 乐园","exEN":"The tiny island with its white beaches looked like a tropical paradise.","exCN":"有着白色沙滩的小岛看上去像一个热带天堂。","extra":""},{"k":"ch1:205","id":205,"word":"drip","phonetic":"/drɪp/","pos":"v.","tag":"高频","meaning":"滴出（液体）；滴下","root":"源自中古英语 dripen（滴下）→ 滴出","exEN":"Rainwater began to drip through a crack in the ceiling during the storm.","exCN":"暴风雨期间，雨水开始从天花板的裂缝中滴下。","extra":""},{"k":"ch1:206","id":206,"word":"drown","phonetic":"/draʊn/","pos":"v.","tag":"高频","meaning":"（使）淹死；浸泡","root":"起源不确定，可能与古英语 druncnian（淹死）有关 → 淹没","exEN":"The low fields near the mouth of the river drown every few years when floods come.","exCN":"河口的低洼田地每隔几年就被洪水淹没一次。","extra":""},{"k":"ch1:207","id":207,"word":"blow","phonetic":"/bləʊ/","pos":"v.","tag":"核心","meaning":"吹；（风）吹","root":"源自古英语 blāwan（吹）→ 吹","exEN":"Strong winds began to blow in from the sea, rattling the wooden shutters.","exCN":"强风开始从海上吹来，吹得木百叶窗咯吱作响。","extra":""},{"k":"ch1:208","id":208,"word":"puff","phonetic":"/pʌf/","pos":"n.","tag":"高频","meaning":"（吹出的）一股，一缕","root":"源自中古英语 puff（一股气）→ 一股","exEN":"A puff of white steam rose from the kettle as the water started to boil.","exCN":"水开始沸腾时，水壶冒出一股白汽。","extra":""},{"k":"ch1:209","id":209,"word":"gush","phonetic":"/ɡʌʃ/","pos":"v.","tag":"高频","meaning":"涌出","root":"可能源自中古英语 guschen（涌出）→ 涌出","exEN":"Muddy water gushed down the street when the neighbourhood drain burst.","exCN":"社区排水管爆裂时，泥水沿街涌下。","extra":""},{"k":"ch1:210","id":210,"word":"dense","phonetic":"/dens/","pos":"adj.","tag":"核心","meaning":"密集的；稠密的","root":"源自拉丁语 densus（稠密的）→ 密集的","exEN":"The dense fog made it impossible to see the road signs clearly.","exCN":"浓雾让人无法看清路牌。","extra":""},{"k":"ch1:211","id":211,"word":"intensity","phonetic":"/ɪnˈtensɪti/","pos":"n.","tag":"核心","meaning":"强度；强烈","root":"intense（强烈的）+ -ity（名词后缀）→ 强度","exEN":"The intensity of the midday sun forced the hikers to rest in the shade.","exCN":"正午强烈的阳光迫使徒步者在阴凉处休息。","extra":""},{"k":"ch1:212","id":212,"word":"intensive","phonetic":"/ɪnˈtensɪv/","pos":"adj.","tag":"核心","meaning":"加强的，集中的，密集的","root":"源自拉丁语 intendere（拉紧；专注）+ -ive → 集中的","exEN":"The team carried out an intensive survey of the volcano after it showed activity.","exCN":"在火山出现活动迹象后，团队对其进行了密集勘测。","extra":""},{"k":"ch1:213","id":213,"word":"emerge","phonetic":"/ɪˈmɜːdʒ/","pos":"v.","tag":"核心","meaning":"浮现，露出；暴露","root":"e（向外）+ merge（浸没）→ 从浸没中出来 → 浮现","exEN":"The tops of the old stone houses slowly emerged as the floodwater retreated.","exCN":"随着洪水退去，旧石屋的屋顶慢慢露了出来。","extra":""},{"k":"ch1:214","id":214,"word":"flash","phonetic":"/flæʃ/","pos":"v.","tag":"核心","meaning":"（使）闪光；（使）闪现；快速发送","root":"可能源自中古英语 flasken（溅出；闪光）→ 闪光","exEN":"An alert notice was flashed to all port workers as the storm approached.","exCN":"暴风雨逼近时，警报通知被迅速发送给所有港口工人。","extra":""},{"k":"ch1:215","id":215,"word":"float","phonetic":"/fləʊt/","pos":"v.","tag":"核心","meaning":"漂浮；飘浮","root":"源自古英语 flotian（漂浮）→ 漂浮","exEN":"Thin sheets of ice still float on the surface of the lake in early spring.","exCN":"早春时节，薄冰层仍漂浮在湖面上。","extra":""},{"k":"ch1:216","id":216,"word":"environment","phonetic":"/ɪnˈvaɪrənmənt/","pos":"n.","tag":"核心","meaning":"自然环境；环境，周围状况","root":"environ（环绕）+ -ment（名词后缀）→ 环境","exEN":"Scientists urged governments to invest more in protecting the coastal environment.","exCN":"科学家敦促政府加大对沿海环境保护的投入。","extra":""},{"k":"ch1:217","id":217,"word":"surrounding","phonetic":"/səˈraʊndɪŋ/","pos":"adj.","tag":"核心","meaning":"周围的，附近的","root":"surround（围绕）+ -ing（形容词后缀）→ 周围的","exEN":"The building and its surrounding fields were swallowed by the rising water.","exCN":"建筑物及其周围的田地被上涨的洪水吞没。","extra":""},{"k":"ch1:218","id":218,"word":"condition","phonetic":"/kənˈdɪʃən/","pos":"n.","tag":"核心","meaning":"条件；情况，状态","root":"源自拉丁语 condicio（协议；条件）→ 条件","exEN":"Roads were closed because of dangerously poor driving conditions after the ice storm.","exCN":"冰暴过后，由于驾驶条件极差且危险，道路被封闭。","extra":""},{"k":"ch1:219","id":219,"word":"situation","phonetic":"/ˌsɪtjuˈeɪʃən/","pos":"n.","tag":"核心","meaning":"情况，处境，形势","root":"源自拉丁语 situs（位置）+ -ation（名词后缀）→ 处境","exEN":"The situation on the flooded plain was described by officials as critical.","exCN":"官员称，被淹没平原上的情况非常危急。","extra":""},{"k":"ch1:220","id":220,"word":"nature","phonetic":"/ˈneɪtʃə/","pos":"n.","tag":"核心","meaning":"大自然；本性；性质","root":"源自拉丁语 natura（出生；本性）→ 自然","exEN":"Walking in nature helps many city workers reduce their daily stress levels.","exCN":"在大自然中散步有助于许多城市工作者降低日常压力。","extra":""},{"k":"ch1:221","id":221,"word":"natural","phonetic":"/ˈnætʃrəl/","pos":"adj.","tag":"核心","meaning":"自然的；天然的","root":"nature（自然）+ -al（形容词后缀）→ 自然的","exEN":"The reserve was created to keep this unique landscape in its natural state.","exCN":"建立保护区是为了让这片独特地貌保持自然原貌。","extra":""},{"k":"ch1:222","id":222,"word":"artificial","phonetic":"/ˌɑːtɪˈfɪʃəl/","pos":"adj.","tag":"核心","meaning":"人造的","root":"art（技巧；人工）+ fic（制作）+ -ial → 人造的","exEN":"An artificial lake was built to provide drinking water for the growing town.","exCN":"修建了一座人工湖为不断扩大的城镇提供饮用水。","extra":""},{"k":"ch1:223","id":223,"word":"synthetic","phonetic":"/sɪnˈθetɪk/","pos":"adj.","tag":"高频","meaning":"人造的，合成的","root":"syn（一起）+ thesis（放置）→ 合成 → 人造的","exEN":"The jacket is filled with a synthetic material that stays warm even when wet.","exCN":"这件夹克填充了一种即使湿了也能保暖的合成材料。","extra":""},{"k":"ch1:224","id":224,"word":"petrol","phonetic":"/ˈpetrəl/","pos":"n.","tag":"高频","meaning":"汽油","root":"源自法语 pétrole（石油）→ 汽油","exEN":"The generator ran out of petrol after working for two hours straight.","exCN":"发电机连续工作两小时后汽油耗尽。","extra":""},{"k":"ch1:225","id":225,"word":"gas","phonetic":"/ɡæs/","pos":"n.","tag":"核心","meaning":"气体；汽油","root":"由比利时化学家 Van Helmont 基于希腊语 chaos（混沌）新造的词 → 气体","exEN":"A faint smell of gas from the stove suggested the pipe needed checking.","exCN":"炉子里隐隐有股煤气味，说明管道需要检查。","extra":""},{"k":"ch1:226","id":226,"word":"gasoline","phonetic":"/ˈɡæsəliːn/","pos":"n.","tag":"高频","meaning":"汽油","root":"gas（气体）+ ol + -ine（化学后缀）→ 汽油","exEN":"The price of gasoline in coastal towns often rises during the summer months.","exCN":"沿海城镇的汽油价格在夏季几个月里经常上涨。","extra":""},{"k":"ch1:227","id":227,"word":"petroleum","phonetic":"/pɪˈtrəʊliəm/","pos":"n.","tag":"高频","meaning":"石油","root":"petr（石头）+ oleum（油）→ 石里的油 → 石油","exEN":"Petroleum remains one of the most traded natural resources in the world.","exCN":"石油仍然是世界上交易量最大的自然资源之一。","extra":""}]};
